verus!{

fn rsplit(a: Vec<String>, sep: String, maxsplit: u8) -> Vec<Vec<String>> 
    ensures(|result: &Vec<Vec<String>>| result.len() == a.len())
    ensures(|result: &Vec<Vec<String>>| {
        forall(|i: usize| (i < a.len()) ==>
            let parts = &result[i];
            parts.len() > 0
            && (maxsplit == 0 ==> parts.len() == 1 && parts[0] == a[i])
            && (a[i].len() == 0 ==> parts.len() == 1 && parts[0].len() == 0)
            && parts.len() <= (maxsplit as usize) + 1
        )
    })
    requires(sep.len() > 0)
{
    // We implement right-split for each string in a, up to maxsplit times, by splitting
    // from the right using the separator string sep.
    // If maxsplit == 0, no splitting is done.
    // If the input string is empty, we return a vector with one empty string.
    // Otherwise, repeatedly find the last separator and split until maxsplit or no separator remains.

    let mut result: Vec<Vec<String>> = Vec::with_capacity(a.len());

    for s in a {
        if maxsplit == 0 {
            // no splitting allowed, return vec with original string
            result.push(vec![s]);
            continue;
        }

        if s.len() == 0 {
            // empty string input returns vec with empty string
            result.push(vec![String::new()]);
            continue;
        }

        // We'll repeatedly find occurrences of sep from the right
        let mut parts_rev: Vec<String> = Vec::new(); // collect parts from right to left
        let mut remaining = s.clone();
        let mut splits_done = 0u8;

        while splits_done < maxsplit {
            // Find last occurrence of sep in remaining
            match remaining.rfind(&sep) {
                Some(pos) => {
                    // split at pos: head = 0..pos, tail = pos+sep.len()..end
                    let tail = remaining[(pos + sep.len())..].to_string();
                    parts_rev.push(tail);
                    remaining = remaining[..pos].to_string();
                    splits_done += 1;
                }
                None => break, // no more sep found
            }
        }

        // Finally push remaining (the leftmost part)
        parts_rev.push(remaining);

        // parts_rev currently holds parts in reverse order, reverse it to obtain parts from left to right
        parts_rev.reverse();

        result.push(parts_rev);
    }

    result
}

}